 * list of non-block scoped variable declarations that appear inside converted loop
 * such variable declarations should be moved outside the loop body
 * for (let x;;) {
 *     var y = 1;
 *     ...
 * }
 * should be converted to
 * var loop = function(x) {
 *    y = 1;
 *    ...
 * }
 * var y;
 * for (var x;;) loop(x);
